impl markup::Transform for super::TrackedRunContent {
    fn transform(&self, ctx: &mut dyn markup::Context) -> Self {
        let node = markup::ask(ctx.wordprocessing(), super::Context::tracked_run, self);
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn markup::Context) -> Self {
        if let Self::Other(node) = self {
            return Self::Other(node.transform(ctx));
        }
        transform_tracked_run_1(self, ctx)
            .or_else(|| transform_tracked_run_2(self, ctx))
            .or_else(|| transform_tracked_run_3(self, ctx))
            .unwrap_or_else(|| self.clone())
    }
}

